<?php
session_start(); require_once __DIR__ . '/../includes/dbconn.php'; require_once __DIR__ . '/../includes/check-login.php'; check_login();
$id=(int)$_SESSION['id'];
$stmt=$mysqli->prepare('SELECT u.firstName,u.lastName,u.regNo,r.roomno,r.seater,r.feespm,r.foodstatus,r.stayfrom,r.duration,r.course FROM userregistration u LEFT JOIN registration r ON r.regno=u.regNo WHERE u.id=? ORDER BY r.id DESC LIMIT 1');
$stmt->bind_param('i',$id);$stmt->execute();$data=$stmt->get_result()->fetch_assoc();$stmt->close();
?>
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تفاصيل الغرفة</title><link href="../assets/css/modern-hostel.css" rel="stylesheet"></head><body><main style="max-width:850px;margin:45px auto;padding:0 18px"><a href="dashboard.php">← لوحة الطالب</a><section class="card" style="margin-top:20px"><div class="card-body"><h1>تفاصيل الغرفة</h1><?php if($data && $data['roomno']!==null): ?><div class="table-responsive"><table class="table"><tbody><?php $items=['اسم الطالب'=>trim($data['firstName'].' '.$data['lastName']),'رقم التسجيل'=>$data['regNo'],'رقم الغرفة'=>$data['roomno'],'عدد الأسرة'=>$data['seater'],'الرسوم الشهرية'=>$data['feespm'],'تاريخ بداية الإقامة'=>$data['stayfrom'],'مدة الإقامة (أشهر)'=>$data['duration'],'البرنامج الدراسي'=>$data['course'],'الوجبات'=>$data['foodstatus']?'مشمولة':'غير مشمولة'];foreach($items as $label=>$value): ?><tr><th><?php echo htmlspecialchars($label,ENT_QUOTES,'UTF-8'); ?></th><td><?php echo htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8'); ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p>لا توجد غرفة مخصصة لحسابك حالياً.</p><?php endif; ?></div></section></main></body></html>